package got.world.genlayer; public class GOTGenLayerIncludeMapRivers extends GOTGenLayer {private final GOTGenLayer mapRiverLayer;public GOTGenLayerIncludeMapRivers(long s,GOTGenLayer river,GOTGenLayer map){super(s);gotParent=river;mapRiverLayer=map;}public void initWorldGenSeed(long s){super.initWorldGenSeed(s);mapRiverLayer.initWorldGenSeed(s);}public int[] getInts(int x,int z,int w,int h){int[] a=gotParent.getInts(x,z,w,h),b=mapRiverLayer.getInts(x,z,w,h);for(int i=0;i<a.length;i++)if(b[i]>=0)a[i]=b[i];return a;}}